// Checks the HMAC signature Convex puts on every loan event.
// The secret comes from the CONVEX_TO_N8N_SECRET env var, never from this workflow.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
const secret = $env.CONVEX_TO_N8N_SECRET;

const reject = (reason) => [{ json: { valid: false, reason } }];
if (!secret) return reject('CONVEX_TO_N8N_SECRET is not set');
if (!/^\d{1,12}$/.test(timestamp) || !signature.startsWith('v1=')) return reject('missing or malformed headers');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('stale timestamp');

// Verify the exact bytes Convex signed, not a re-serialised copy of the JSON.
if (!item.binary || !item.binary.data) return reject('no raw body');
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest();
const given = Buffer.from(signature.slice(3), 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
  return reject('bad signature');
}

return [{ json: { valid: true, event: JSON.parse(raw) } }];

// Builds the email from the minimal event Convex sent: recipient name and
// email, the other person's display name, the tool name and the dates.
const e = $json.event;
const dates = e.startDate === e.endDate ? e.startDate : e.startDate + ' to ' + e.endDate;
const who = e.counterpartyName;
const tool = e.toolName;

const templates = {
  'loan.requested': [who + ' wants to borrow your ' + tool, who + ' asked to borrow your ' + tool + ' for ' + dates + '. Open LendLoop to approve or decline.'],
  'loan.approved':  ['Your request for the ' + tool + ' was approved', who + ' approved your request for ' + dates + '. Arrange the handover in LendLoop.'],
  'loan.declined':  ['Your request for the ' + tool + ' was declined', 'Your request for ' + dates + " couldn't be accepted this time. Have a look for something similar on LendLoop."],
  'loan.cancelled': [who + ' cancelled their request', who + ' cancelled their request to borrow your ' + tool + ' for ' + dates + '.'],
  'loan.returned':  ['Thanks for returning the ' + tool, who + ' confirmed the ' + tool + ' is back. Thanks for borrowing responsibly!'],
};
const pair = templates[e.type];
if (!pair) throw new Error('Unknown event type: ' + e.type);

return {
  json: {
    idempotencyKey: 'notification:' + e.eventId,
    loanId: e.loanId,
    type: e.type,
    to: e.recipient.email,
    subject: pair[0],
    text: 'Hi ' + e.recipient.name + ',\n\n' + pair[1] + '\n\nLendLoop',
  },
};

// Mock email provider: logs instead of sending. To go live, replace this node
// with a Gmail / SMTP / SendGrid node and keep the same retry and
// "continue (using error output)" settings.
// Addresses ending in @fail.test simulate a provider outage, to demo the
// retry → failed write-back path.
const to = $json.to;
if (to.endsWith('@fail.test')) {
  throw new Error('Mock provider: mailbox unavailable');
}
// Log a masked address only: execution logs are not the place for PII.
const masked = to.replace(/^(.).*@/, '$1***@');
console.log('[mock-email] to=' + masked + ' subject="' + $json.subject + '"');
return { json: { delivered: true, channel: 'mock-email' } };

const crypto = require('crypto');

// Signs a body for Convex with N8N_TO_CONVEX_SECRET (an env var, never stored
// in this workflow). Convex checks the signature and rejects timestamps older
// than 5 minutes.
function signForConvex(payload) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { body, timestamp, signature };
}

// Runs for both outputs of "Send email (mock)": success and error.
const msg = $('Compose message').item.json;
const sent = $json.delivered === true;
const DETAIL = {
  'loan.requested': 'Lender told about the request',
  'loan.approved': 'Borrower told it was approved',
  'loan.declined': 'Borrower told it was declined',
  'loan.cancelled': 'Lender told it was cancelled',
  'loan.returned': 'Borrower thanked for returning it',
};

return {
  json: signForConvex({
    idempotencyKey: msg.idempotencyKey,
    loanId: msg.loanId,
    kind: 'notification',
    status: sent ? 'sent' : 'failed',
    channel: 'mock-email',
    detail: sent ? DETAIL[msg.type] : 'Email failed after 3 tries',
  }),
};
